{
  "@id": "srv0-u982998-p443",
  "handle": [
    {
      "handler": "reverse_proxy",
      "transport": {
        "protocol": "http",
        "tls": {
          "server_name": "<redacted-host>"
        }
      },
      "upstreams": [
        {
